這是一個簡單的 debounce 實作，並附上使用範例：

```javascript
/**
 * 建立一個 debounce 包裝函式
 * @param {Function} fn - 要被防抖動的函式
 * @param {number} delay - 等待的毫秒數
 * @param {boolean} [immediate=false] - 是否在前緣（第一次呼叫時）立即執行
 * @returns {Function} 包裝後的函式，附帶 cancel() 方法
 */
function debounce(fn, delay, immediate = false) {
  let timer = null;

  function debounced(...args) {
    const callNow = immediate && !timer;

    clearTimeout(timer);

    timer = setTimeout(() => {
      timer = null;
      if (!immediate) {
        fn.apply(this, args);
      }
    }, delay);

    if (callNow) {
      fn.apply(this, args);
    }
  }

  // 取消尚未執行的呼叫
  debounced.cancel = () => {
    clearTimeout(timer);
    timer = null;
  };

  return debounced;
}

// ===== 使用範例 =====

// 模擬搜尋功能：只有在使用者停止輸入 300ms 後才送出請求
const search = (query) => {
  console.log(`搜尋：${query}`);
};

const debouncedSearch = debounce(search, 300);

// 模擬快速連續輸入
debouncedSearch('a');
debouncedSearch('ab');
debouncedSearch('abc');
// 只會輸出一次：搜尋：abc（約 300ms 後）

// 使用 immediate 模式：第一次呼叫立即執行，之後的呼叫在停止 500ms 後才能再次觸發
const save = () => console.log('已儲存');
const debouncedSave = debounce(save, 500, true);

debouncedSave(); // 立即輸出：已儲存
debouncedSave(); // 被忽略，重新計時
debouncedSave(); // 被忽略，重新計時

// 取消待執行的呼叫
debouncedSearch('xyz');
debouncedSearch.cancel(); // 不會有任何輸出
```

**運作原理：**
- 每次呼叫時先清除舊的計時器，再設定新的計時器。
- 只有當呼叫停止、等待滿 `delay` 毫秒後，才真正執行原函式。
- `immediate` 參數可讓函式在一連串呼叫的「第一次」就立即執行。
- `cancel()` 可以取消尚未執行的呼叫。

```javascript
/**
 * 建立一個防抖（debounce）函式：在最後一次呼叫後等待 delay 毫秒才執行。
 * @param {Function} fn 要防抖的函式
 * @param {number} delay 等待時間（毫秒）
 * @returns {Function} 防抖後的函式，附帶 cancel() 方法
 */
function debounce(fn, delay) {
  let timer = null;

  function debounced(...args) {
    clearTimeout(timer);
    timer = setTimeout(() => {
      timer = null;
      fn.apply(this, args);
    }, delay);
  }

  debounced.cancel = () => {
    clearTimeout(timer);
    timer = null;
  };

  return debounced;
}

// 使用範例：搜尋輸入框
const search = debounce((keyword) => {
  console.log(`搜尋：${keyword}`);
}, 300);

// 模擬快速輸入
search('j');
search('ja');
search('jav');
search('java');
// 只會在最後一次呼叫 300ms 後輸出：搜尋：java

// 取消尚未執行的呼叫
search('javascript');
search.cancel(); // 不會有輸出
```

