以下是 debounce 函式的實作與使用範例：

```javascript
/**
 * 建立一個防抖（debounce）函式。
 * 在最後一次呼叫後等待 `wait` 毫秒才執行原函式。
 *
 * @param {Function} fn - 要防抖的函式
 * @param {number} wait - 等待時間（毫秒）
 * @param {Object} [options]
 * @param {boolean} [options.leading=false] - 是否在等待開始時立即執行
 * @returns {Function} 防抖後的函式，附有 cancel() 與 flush() 方法
 */
function debounce(fn, wait = 300, options = {}) {
  const { leading = false } = options;
  let timerId = null;
  let lastArgs = null;
  let lastThis = null;
  let result;

  function invoke() {
    const args = lastArgs;
    const context = lastThis;
    lastArgs = lastThis = null;
    result = fn.apply(context, args);
    return result;
  }

  function debounced(...args) {
    lastArgs = args;
    lastThis = this;

    const callNow = leading && timerId === null;

    clearTimeout(timerId);
    timerId = setTimeout(() => {
      timerId = null;
      if (!leading) invoke();
    }, wait);

    if (callNow) invoke();
    return result;
  }

  debounced.cancel = function () {
    clearTimeout(timerId);
    timerId = lastArgs = lastThis = null;
  };

  debounced.flush = function () {
    if (timerId === null) return result;
    clearTimeout(timerId);
    timerId = null;
    return invoke();
  };

  return debounced;
}
```

### 使用範例

```javascript
// 1. 基本用法：停止輸入 300ms 後才搜尋
const input = document.querySelector('#search');

const search = debounce((keyword) => {
  console.log('搜尋：', keyword);
}, 300);

input.addEventListener('input', (e) => {
  search(e.target.value);
});

// 2. leading 模式：第一次呼叫立即執行，之後的連續呼叫在停止後才再執行一次
const save = debounce(() => {
  console.log('已儲存');
}, 1000, { leading: true });

// 3. 取消與立即執行
const log = debounce((msg) => console.log(msg), 500);
log('hello');   // 500ms 後才輸出
log.cancel();   // 取消待執行的呼叫（不會輸出）
log('world');
log.flush();    // 立即執行，輸出 "world"
```

### 說明

- **基本行為**：每次呼叫都會重設計時器，只有在 `wait` 毫秒內沒有新的呼叫時，才會執行一次原函式。
- **`leading` 選項**：設為 `true` 時，第一次呼叫會立即執行，之後的連續呼叫會被延後，直到停止呼叫後再執行一次。
- **`cancel()`**：取消尚未執行的呼叫。
- **`flush()`**：立即執行尚未執行的呼叫。
- **保留 `this` 與參數**：會使用最後一次呼叫時的 `this` 與參數。

```javascript
/**
 * 建立一個 debounce 函式：在最後一次呼叫後等待 wait 毫秒才執行。
 * @param {Function} fn 要防抖的函式
 * @param {number} wait 等待毫秒數
 * @param {{ leading?: boolean }} [options] leading 為 true 時於第一次呼叫立即執行
 * @returns {Function & { cancel: () => void }}
 */
function debounce(fn, wait, options = {}) {
  const { leading = false } = options;
  let timer = null;
  let lastArgs = null;
  let lastThis = null;

  function debounced(...args) {
    const callNow = leading && timer === null;
    lastArgs = args;
    lastThis = this;

    clearTimeout(timer);
    timer = setTimeout(() => {
      timer = null;
      if (!leading) {
        fn.apply(lastThis, lastArgs);
      }
    }, wait);

    if (callNow) {
      fn.apply(lastThis, lastArgs);
    }
  }

  debounced.cancel = () => {
    clearTimeout(timer);
    timer = null;
    lastArgs = null;
    lastThis = null;
  };

  return debounced;
}

// 使用範例
const search = debounce((keyword) => {
  console.log("搜尋：", keyword);
}, 300);

search("a");
search("ap");
search("app");
search("apple"); // 只有最後一次會在 300ms 後執行 → 輸出：搜尋： apple

// leading 模式：第一次立即執行，之後 300ms 內的呼叫被忽略
const save = debounce(() => console.log("已儲存"), 300, { leading: true });
save(); // 立即輸出：已儲存
save(); // 被忽略

// 取消待執行的呼叫
search.cancel();
```

